    assert check_item_type_name("ab*cd") == "ab_cd"
    assert check_item_type_name('ab"cd') == "ab_cd"
    assert check_item_type_name("ab<cd") == "ab_cd"
    assert check_item_type_name("ab>cd") == "ab_cd"


