# .tox/c1/bin/pytest --cov=weko_items_ui tests/test_utils.py::test_export_items_issue50961 -vv -s --cov-branch --cov-report=term --basetemp=/code/modules/weko-items-ui/.tox/c1/tmp
def test_export_items_issue50961(app,db_itemtype,db_records,users):
    post_data = {'export_file_contents_radio': 'False', 'record_ids': '[1]', 'invalid_record_ids': '[]'}
    with app.test_request_context(headers=[("Accept-Language", "en")]):
        with patch("flask_login.utils._get_user", return_value=users[1]["obj"]):
            # KeyError
            pytest.raises(BadRequest, export_items, post_data)

            # TypeError
            post_data["export_format_radio"] = "JSON"
            post_data["record_ids"] = 1
            pytest.raises(BadRequest, export_items, post_data)

            # ValueError
            post_data["record_ids"] = "[1]"
            post_data["invalid_record_ids"] = '["test"]'
            pytest.raises(BadRequest, export_items, post_data)

            # JSONDecodeError
            post_data["invalid_record_ids"] = "1,2"
            pytest.raises(BadRequest, export_items, post_data)


# def write_rocrate(item_types_data, export_path, list_item_role):
# .tox/c1/bin/pytest --cov=weko_items_ui tests/test_utils.py::test_write_rocrate -vv -s --cov-branch --cov-report=term --basetemp=/code/modules/weko-items-ui/.tox/c1/tmp
def test_write_rocrate(app,client,db_itemtype,db_records,users,mocker):
    item_types_data = {
        '1': {
            'item_type_id': '1',
            'name': 'itemtype',
            'root_url': 'https://localhost:8443/',
            'jsonschema': 'items/jsonschema/1',
            'keys': [],
            'labels': [],
            'recids': [1],
            'data': {}
        }
    }
    export_path = tempfile.mkdtemp()
    list_item_role = {'1': {'weko_creator_id': '1', 'weko_shared_id': -1}}

    # ElasticSearchからのメタデータ取得をモック
    mock_metadata = {'1': ('テストタイトル', ['file1.txt', 'file2.txt'])}
    mocker.patch("weko_items_ui.utils._get_metadata_dict_in_es", return_value=mock_metadata)

    # JsonldMapping, JsonLdMapper, bagit, shutil.make_archive, shutil.rmtree, open, send_file などをモック
    mock_mapping = MagicMock()
    mock_mapping.mapping = {"@context": {}, "@graph": []}
    mocker.patch("weko_items_ui.utils.JsonldMapping.get_by_itemtype_id", return_value=[mock_mapping])
    mock_mapper = MagicMock()
    mock_mapper.is_valid = True
    mock_mapper.json_mapping = {"@context": {}, "@graph": []}
    mock_mapper.to_rocrate_metadata.return_value.metadata.generate.return_value = {"@graph": []}
    mocker.patch("weko_items_ui.utils.JsonLdMapper", return_value=mock_mapper)
    mocker.patch("weko_items_ui.utils.bagit.make_bag")
    mocker.patch("weko_items_ui.utils.shutil.make_archive")
    mocker.patch("weko_items_ui.utils.shutil.rmtree")
    mocker.patch("builtins.open", mocker.mock_open())

    # README.mdのコピーもモック
    mocker.patch("weko_items_ui.utils.shutil.copyfile")

    with app.test_request_context(headers=[("Accept-Language", "en")]):
        write_rocrate(item_types_data, export_path, list_item_role)

    # RO-Crateファイルが作成されることを確認
    readme_path = os.path.join(export_path, "README.md")
    assert os.path.exists(export_path)


# def _get_metadata_dict_in_es(record_ids):
# .tox/c1/bin/pytest --cov=weko_items_ui tests/test_utils.py::test_get_metadata_dict_in_es_success -vv -s --cov-branch --cov-report=term --basetemp=/code/modules/weko-items-ui/.tox/c1/tmp
def test_get_metadata_dict_in_es_success(app, mocker):
    record_ids = ["1"]
    mock_search = MagicMock()
    mock_execute = MagicMock()
    mock_execute.to_dict.return_value = {
        "hits": {
            "hits": [
                {
                    "sort": ["1"],
                    "_source": {
                        "title": ["タイトル1"],
                        "content": [
                            {"filename": "file1.txt", "attachment": True}
                        ]
                    }
                }
            ]
        }
    }
    mock_search.execute.return_value = mock_execute
    mock_search.filter.return_value = mock_search
    mock_search.sort.return_value = mock_search
    mock_search.source.return_value = mock_search
    mock_search.params.return_value = mock_search

    mocker.patch("weko_items_ui.utils.RecordsSearch", return_value=mock_search)
    mock_current_app = MagicMock()
    mock_current_app.config = {"SEARCH_UI_SEARCH_INDEX": "test-index"}
    mocker.patch("weko_items_ui.utils.current_app", mock_current_app)

    result = _get_metadata_dict_in_es(record_ids)
    assert result == {
        "1": ("タイトル1", ["file1.txt"])
    }


