# .tox/c1/bin/pytest --cov=weko_items_ui tests/test_utils.py::test_get_file_download_data -vv -s --cov-branch --cov-report=html --cov-report=term --basetemp=/code/modules/weko-items-ui/.tox/c1/tmp
def test_get_file_download_data(app, client, records):
    indexer, results = records

    with app.test_request_context():
        # 12 Can sort download_total
        record = results[1]["record"]
        filenames = ["helloworld.pdf", "helloworld.docx"]
        for file in record.files:
            file["accessrole"] = "open_access"
            file["filename"] = file["key"]
        return_value = {
            'download_ranking': {
                'doc_count_error_upper_bound': 0,
                'sum_other_doc_count': 0,
                'buckets': [
                    {
                        'key': filenames[1],
                        'doc_count': 3
                    },
                    {
                        'key': filenames[0],
                        'doc_count': 5
                    },
                ]
            }
        }
        with patch("invenio_stats.queries.ESWekoFileRankingQuery.run", return_value=return_value):
            res = get_file_download_data(record.id, record, filenames)
            assert res["ranking"][0]["download_total"] == 5
            assert res["ranking"][1]["download_total"] == 3

        # 13 Both accessrole
        record = results[3]["record"]
        filenames = ["helloworld.pdf", "helloworld.txt"]
        accessrole_list = ["open_access", "open_no"]
        for file, accessrole in zip(record.files, accessrole_list):
            file["accessrole"] = accessrole
            file["filename"] = file["key"]
        return_value = {
            'download_ranking': {
                'doc_count_error_upper_bound': 0,
                'sum_other_doc_count': 0,
                'buckets': [
                    {
                        'key': filenames[0],
                        'doc_count': 5
                    },
                    {
                        'key': filenames[1],
                        'doc_count': 3
                    },
                ]
            }
        }
        with patch("invenio_stats.queries.ESWekoFileRankingQuery.run", return_value=return_value):
            res = get_file_download_data(record.id, record, filenames)
            assert len(res["ranking"]) == 1
            assert res["ranking"][0]["filename"] == "helloworld.pdf"

        # 14 Set date
        with patch("invenio_stats.queries.ESWekoFileRankingQuery.run", return_value=return_value) as test_mock:
            res = get_file_download_data(record.id, record, filenames, "2024-01")
            assert test_mock.call_args[1]["start_date"] == "2024-01-01"
            assert test_mock.call_args[1]["end_date"] == "2024-01-31T23:59:59"

        # 15 Set size
        record = results[1]["record"]
        filenames = ["helloworld.pdf", "helloworld.docx"]
        for file in record.files:
            file["accessrole"] = "open_access"
            file["filename"] = file["key"]
        return_value = {
            'download_ranking': {
                'doc_count_error_upper_bound': 0,
                'sum_other_doc_count': 0,
                'buckets': [
                    {
                        'key': filenames[0],
                        'doc_count': 3
                    },
                    {
                        'key': filenames[1],
                        'doc_count': 5
                    },
                ]
            }
        }
        with patch("invenio_stats.queries.ESWekoFileRankingQuery.run", return_value=return_value):
            res = get_file_download_data(record.id, record, filenames, size=1)
            assert len(res["ranking"]) == 1
            assert res["ranking"][0]["download_total"] == 5

        # 16 Exeption in running query
        with patch("invenio_stats.queries.ESWekoFileRankingQuery.run", side_effect=Exception):
            res = get_file_download_data(record.id, record, filenames)
            assert res["ranking"][0]["download_total"] \
                    == res["ranking"][1]["download_total"] \
                    == 0

        with patch("invenio_stats.queries.ESWekoFileRankingQuery.run", return_value=Exception):
            res = get_file_download_data(record.id, record, filenames)
            assert res["ranking"][0]["download_total"] \
                    == res["ranking"][1]["download_total"] \
                    == 0

        # 17 Only unavailable file
        record = results[4]["record"]
        filenames = ["helloworld.pdf"]
        for file in record.files:
            file["accessrole"] = "open_no"
            file["filename"] = file["key"]
        with pytest.raises(AvailableFilesNotFoundRESTError):
            get_file_download_data(record.id, record, filenames)

        # 18 Not exist file
        record = results[5]["record"]
        with pytest.raises(AvailableFilesNotFoundRESTError):
            get_file_download_data(record.id, record, filenames)

# .tox/c1/bin/pytest --cov=weko_items_ui tests/test_utils.py::test_get_duplicate_fields -vv -s --cov-branch --cov-report=term --basetemp=/code/modules/weko-items-ui/.tox/c1/tmp
def test_get_duplicate_fields():
    data_author_list = [
        {
            "creatorNames":[
                {"creatorName":"情報, 太郎"},
                {"creatorName":"じょうほう, たろう"},
            ],
            "nameIdentifiers":[
                {"nameIdentifierScheme":"WEKO","nameIdentifier":"6","nameIdentifierURI":"https://test.uri"},
                {"nameIdentifierScheme":"ORCID","nameIdentifier":"6.123","nameIdentifierURI":"https://test.orcid.uri"},
            ]
        },
        {
            "creatorNames":[
                {"creatorName":"じょうほう, じろう"},
                {"creatorName":"情報, 次郎"},
            ],
            "nameIdentifiers":[
                {"nameIdentifierScheme":"ORCID","nameIdentifier":"7.123","nameIdentifierURI":"https://test.orcid.uri"},
                {"nameIdentifierScheme":"WEKO","nameIdentifier":"7","nameIdentifierURI":"https://test.uri"},
            ]
        }
    ]
    res = get_duplicate_fields(data_author_list)
    assert res[0] == []
    assert res[1] == []
    assert res[2] == []
    assert res[3] == ["情報, 太郎", "じょうほう, たろう", "じょうほう, じろう", "情報, 次郎"]
    assert res[4] == ["6", "7"]

    data_author_dict = {
        "creatorNames":[
            {"creatorName":"情報, 太郎"},
            {"creatorName":"じょうほう, たろう"},
        ],
        "nameIdentifiers":[
            {"nameIdentifierScheme":"WEKO","nameIdentifier":"6","nameIdentifierURI":"https://test.uri"},
            {"nameIdentifierScheme":"ORCID","nameIdentifier":"6.123","nameIdentifierURI":"https://test.orcid.uri"},
        ]
    }
    res = get_duplicate_fields(data_author_dict)
    assert res[0] == []
    assert res[1] == []
    assert res[2] == []
    assert res[3] == ["情報, 太郎", "じょうほう, たろう"]
    assert res[4] == ["6"]

    data_title_list = [
        {
            "subitem_title": "テストタイトル",
            "subitem_title_language": "ja"
        },
        {
            "subitem_title": "test title",
            "subitem_title_language": "en"
        }
    ]
    res = get_duplicate_fields(data_title_list)
    assert res[0] == []
    assert res[1] == []
    assert res[2] == ["テストタイトル", "test title"]
    assert res[3] == []
    assert res[4] == []

    data_title_dict = {
        "subitem_title": "テストタイトルその2",
        "subitem_title_language": "ja"
    }
    res = get_duplicate_fields(data_title_dict)
    assert res[0] == []
    assert res[1] == []
    assert res[2] == ["テストタイトルその2"]
    assert res[3] == []
    assert res[4] == []


    data_idt_list = [
        {
            "subitem_identifier_uri": "5678",
            "subitem_identifier_type": "DOI",
        },
        {
            "subitem_identifier_uri": "90123",
            "subitem_identifier_type": "URI",
        },
    ]
    res = get_duplicate_fields(data_idt_list)
    assert res[0] == []
    assert res[1] == ["5678","90123"]
    assert res[2] == []
    assert res[3] == []
    assert res[4] == []

    data_idt_dict = {
        "subitem_identifier_uri": "12345",
        "subitem_identifier_type": "DOI",
    }
    res = get_duplicate_fields(data_idt_dict)
    assert res[0] == []
    assert res[1] == ["12345"]
    assert res[2] == []
    assert res[3] == []
    assert res[4] == []

    data_resourcetype_list = [
        {
            "resourcetype": "data paper",
            "resourceuri": "http://purl.org/coar/resource_type/c_beb9"
        },
        {
            "resourcetype": "journal",
            "resourceuri": "http://purl.org/coar/resource_type/c_0640/"
        },
    ]
    res = get_duplicate_fields(data_resourcetype_list)
    assert res[0] == ["data paper", "journal"]
    assert res[1] == []
    assert res[2] == []
    assert res[3] == []
    assert res[4] == []
    data_resourcetype_dict = {
            "resourcetype": "conference paper",
            "resourceuri": "http://purl.org/coar/resource_type/c_5794"
    }
    res = get_duplicate_fields(data_resourcetype_dict)
    assert res[0] == ["conference paper"]
    assert res[1] == []
    assert res[2] == []
    assert res[3] == []
    assert res[4] == []



# def check_duplicate(data, is_item=True):
# .tox/c1/bin/pytest --cov=weko_items_ui tests/test_utils.py::test_check_duplicate -v --cov-branch --cov-report=term --basetemp=/code/modules/weko-items-ui/.tox/c1/tmp
def test_check_duplicate(app, users,db_records3):
    with app.test_request_context():
        # Duplicate check disabled
        app.config["WEKO_ITEMS_UI_ENABLE_DUPLICATE_CHECK"] = False
        res, [], [] =  check_duplicate('',True)
        assert res == False
        
        app.config["WEKO_ITEMS_UI_ENABLE_DUPLICATE_CHECK"] = True
        # JSON format NG
        res, [], [] =  check_duplicate('',True)
        assert res == False

        # data dict NG
        res, [], [] =  check_duplicate(1,True)
        assert res == False

        # metadata format NG
        res, [], [] =  check_duplicate({"metainfo":123},False)
        assert res == False

        # first_item not dict
        res, [], [] =  check_duplicate({"subitem_identifier_uri":[{"subitem_identifier_uri"}]},True)
        assert res == False

        # subitem_identifier_uri NG
        res, [], [] =  check_duplicate({"subitem_identifier_uri":[{"subitem_identifier_uri":"noexists"}]},True)
        assert res == False

        # subitem_identifier_uri OK
        res, recid_list, item_links =  check_duplicate({"subitem_identifier_uri":[{"subitem_identifier_uri":"http://localhost"}]},True)
        assert recid_list[0] == 8

        # subitem_title NG
        res, [], [] =  check_duplicate({"subitem_title":[{"subitem_title":"title"}]},True)
        assert res == False

        # subitem_title:T  resource_type:T
        res, [], [] =  check_duplicate({"subitem_title":[{"subitem_title":"タイトル"}],"resourcetype":{"resourcetype":"Resource Type"}},True)
        assert res == False

        # creatorNames NG
        res, [], [] =  check_duplicate({"creatorNames":[{"creatorNames":[{"creatorName":"test"}]}]},True)
        assert res == False

        # creatorNames OK
        res, recid_list, item_links =  check_duplicate({"creatorNames":[{"creatorNames":[{"creatorName":"情報, 太郎"}, {"creatorName":"ジョウホウ, タロウ"}, {"creatorName":"Joho, Taro"}], "subitem_title":"タイトル", "resourcetype":"Resource Type"},
                                                                        {"creatorNames":[{"creatorName":"情報, 次郎"}, {"creatorName":"ジョウホウ, タロウ"}, {"creatorName":"Joho, Taro"}]},
                                                                        {"creatorNames":[{"creatorName":"情報, 三郎"}, {"creatorName":"ジョウホウ, タロウ"}, {"creatorName":"Joho, Taro"}]},
                                                                        ]},True)
        assert recid_list[0] == 8

        # resourcetype
        res, [], [] =  check_duplicate({"resourcetype":{"resourcetype":"test"}},True)
        assert res == False


