        app.config["WEKO_ITEMS_UI_CONTRIBUTOR_SUGGEST_LIMIT"] = 1
        result = search_role_name("alp")
        assert result["count"] == 2
        assert result["has_more"] is True
        assert len(result["results"]) == 1


